def calendar_escape(value):
    return value.replace('\\','\\\\').replace('\n','\\n').replace(';','\\;').replace(',','\\,')

def folded(line):
    # RFC 5545: folds use CRLF + space; each physical line is <=75 UTF-8 octets.
    pieces=[];current='';size=0
    for char in line:
        length=len(char.encode('utf-8'))
        if size+length>75:pieces.append(current);current=' ';size=1
        current+=char;size+=length
    return '\r\n'.join(pieces+[current])

def calendars():
    target=ROOT/'calendars';target.mkdir(exist_ok=True)
    for group in GROUPS:
        tour=BY_ID[group['id']]
        description=f'PROPOSED DATES ONLY. This calendar entry is not a booking. Arrive {date_label(group["arrival"])}; activity begins {date_label(group["start"])}; departure {date_label(group["departure"])}. {group["event"]}. Confirm the viable group, operating arrangements, itinerary, quote and terms with David before buying flights. Mountain plans depend on conditions and the guide’s safety decisions.'
        lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//David Explora//Proposed journeys//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT','UID:'+group['id']+'-2026@david-explora.fastash16.chatgpt.site','DTSTAMP:20261014T000000Z','DTSTART;VALUE=DATE:'+group['arrival'].replace('-',''),'DTEND;VALUE=DATE:'+(date.fromisoformat(group['departure'])+timedelta(days=1)).strftime('%Y%m%d'),'STATUS:TENTATIVE','TRANSP:TRANSPARENT','SUMMARY:'+calendar_escape('Proposed · '+tour['title']),'DESCRIPTION:'+calendar_escape(description),'URL:'+site.ORIGIN+'/'+group['id']+'.html','END:VEVENT','END:VCALENDAR']
        (target/(group['id']+'.ics')).write_bytes(('\r\n'.join(map(folded,lines))+'\r\n').encode('utf-8'))

